"""Word-class sketch of layers.15.mlp.down_proj component 2380.

The component is almost entirely MLP hidden unit 2380 of layer 15, scaled by its output
norm: its activation is about 1.03 * silu(gate) * up, and that unit makes up about 60% of
its variance. Large values need the gate open (positive); the sign then follows the up
projection, which leans positive after object pronouns and copulas ("them", "it", "are",
"is") and negative after determiners, possessives and quantifiers ("your", "his", "entire",
"all of", "portion of").

The rest of its variance is context that a word list does not capture (neither the
current token, the previous token, nor a bag of recent tokens explains much). So this
program only gives the average value of each word class and is near zero elsewhere.
The values are rounded class means measured on training text.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

OBJECT_PRONOUNS = {"them", "him", "it"}
COPULAS = {"is", "are", "was", "were", "be"}
DETERMINERS = {"your", "his", "their", "its", "our", "my", "these", "those", "entire", "whole"}
QUANTIFIERS = {"all", "none", "much", "many", "most", "each", "some", "both", "portion", "ml"}


def word(token: str) -> str:
    return token.strip().lower()


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0  # a document's first token has almost no activation
    now = word(prefix.token_strings[-1])
    before = word(prefix.token_strings[-2])
    if now in OBJECT_PRONOUNS:
        value = 0.4
    elif now in COPULAS:
        value = 0.12
    elif now == "of" and before in QUANTIFIERS:
        value = -0.45
    elif now in DETERMINERS:
        value = -0.2
    else:
        value = 0.045  # the component's average value on other words
    return carry, float(value)

"""Negative activation on additive "also"-type words, scaled by the word before them.

Component p-82af68dd@100000/layers.15.mlp.down_proj:2381 writes into the residual stream
with a negative sign on "also" and its equivalents in other languages (too, likewise,
auch, aussi, también, также, тоже, 也, も, ...). It is strongest when "also" sits
mid-clause, after a verb, copula or modal ("is also", "was also", "must also", "which
also"), and weakest after a conjunction ("and also", "but also"). Weaker negative values
go to "same", "again", "another", "still", "well" and "similar", and to the verb or
determiner right after an "also" ("also be", "also a", "also in"). Everything else is 0.

The predicted levels are group means, so the program captures the sign and the typical
size of each case. It does not capture the large spread inside each group.
"""

from collections.abc import Mapping

READS = ()

ALSO_WORDS = {
    "also", "too", "likewise", "similarly", "equally", "auch", "aussi", "también",
    "também", "ebenfalls", "également", "også", "även", "тоже", "также", "же", "cũng",
    "亦", "也", "也是", "也有", "同样", "同樣", "も", "にも", "でも", "도",
}  # fmt: skip

# Words that mean "the same", "once more" or "in addition" in the same way.
SAME_WORDS = {"same", "again", "another", "still", "well", "similar"}

# Verbs and determiners that often follow "also" directly ("also be", "also a").
AFTER_ALSO = {"be", "been", "a", "an", "in", "has", "have", "to", "is", "are", "was", "of"}

AUXILIARIES = {
    "is", "are", "was", "were", "be", "been", "being", "am", "has", "have", "had",
    "can", "could", "will", "would", "shall", "should", "may", "might", "must",
    "do", "does", "did",
}  # fmt: skip
RELATIVES = {"which", "who", "that", "this"}
SUBJECT_PRONOUNS = {"he", "she", "they", "we", "it", "i", "you", "there"}
PUNCTUATION = {",", ".", ";", ":", "(", ")", "\n", ""}
CONJUNCTIONS = {"and", "but", "or", "while", "so", "then"}


def also_level(before: str) -> float:
    """Activation for "also"-type words, given the word right before them."""
    if before in AUXILIARIES:
        return -7.0
    if before in RELATIVES:
        return -11.0
    if before in PUNCTUATION:
        return -4.0
    if before in SUBJECT_PRONOUNS:
        return -3.0
    if before in CONJUNCTIONS:
        return -1.0
    return -5.0


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in ALSO_WORDS:
        return carry, also_level(before)
    if word in SAME_WORDS:
        return carry, -2.0
    if before in ALSO_WORDS and word in AFTER_ALSO:
        return carry, -3.0
    return carry, 0.0

"""Layer-15 MLP unit 2386 (down_proj component 2386), read as a rough word-level rule.

What it is: the component reads the layer-15 MLP hidden state through one direction. Its
largest read weight is on hidden unit 2386 of that MLP (0.54; the next largest is 0.06).
Its activation is mostly small and diffuse, roughly symmetric around 0 (std 0.35), with
rare large positive spikes. The largest spikes (up to about 10) fall on the words of the
assistant's stock self-description, "I'm sorry, but as an AI language model": the "an"
after "as", the "AI", and "model". Smaller positive values follow the subject pronouns
"I", "we", "they" and "you". Negative values follow negations and modal verbs ("not",
"should", "can"), where a bare verb is due next.

What it predicts: a fixed value per word, with no memory across tokens. It explains almost
none of the activation's variance (about 0.2% on eval). Token identity alone explains
essentially nothing, and the rest is contextual, with no concept found that carries it.
"""

READS = ()

PRONOUN_SUBJECTS = {"i", "we", "they", "you"}
NEGATIONS = {"not", "no", "never"}
MODALS = {"can", "could", "will", "would", "should", "may", "might", "must"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    ids, docs, strings = prefix.token_ids, prefix.document_ids, prefix.token_strings
    cur = _word(strings[t])
    prev = _word(strings[t - 1]) if t > 0 and docs[t - 1] == docs[t] else ""
    recent = [_word(s) for s in strings[max(0, t - 4):t]]
    if prev == "as" and cur == "an":
        return carry, 0.7
    if cur == "ai" and prev in ("an", "a"):
        return carry, 0.7
    if cur in ("model", "language") and "ai" in recent:
        return carry, 0.5
    if cur in PRONOUN_SUBJECTS:
        return carry, 0.15
    if cur in NEGATIONS:
        return carry, -0.1
    if cur in MODALS:
        return carry, -0.05
    return carry, -0.03

"""Layer 15 MLP hidden unit 2400, as seen through down_proj component 2400.

What the component is: one rank-one piece of layers.15.mlp.down_proj. Its activation is
(hidden . V) * |U|, and its V weights mostly MLP hidden unit 2400 plus many small weights
on other units. Its activation is mostly small noise (std about 0.4, both signs), with
rare spikes of about 3 to 5 on about 0.06% of tokens. The spikes fall on content words
that open a noun phrase, such as "tax" in "the tax", "test" in "a test", and "black" in
"black hole". Token identity, part of speech and word frequency explain little of the
spread, so this program predicts only the coarse average pattern, not the spikes.

What the program predicts at each token:
  - the first token of a document: 0, the unit is silent there;
  - the 2nd and 3rd tokens of a document: a small positive mean;
  - tokens 4 to 10 of a document: a smaller positive mean;
  - later word tokens right after "the", "a" or "an": a small positive mean;
  - later word tokens right after a preposition: about 0;
  - other later word tokens: a small negative mean;
  - later punctuation, digits and other non-word tokens: a small positive mean.
"""
import re

READS = ()

WORD = re.compile(r"\s?[A-Za-z]+")
AFTER_DETERMINER = {" the", " a", " an"}
AFTER_PREPOSITION = {" of", " to", " in", " for", " with", " by", " on", " at", " from"}


def step(carry, prefix, upstream):
    """Predicted activation at the newest token; carry is its position in the document."""
    docs = prefix.document_ids
    new_doc = len(docs) < 2 or docs[-1] != docs[-2]
    pos = 0 if new_doc or carry is None else carry + 1
    if pos == 0:
        return pos, 0.0
    if pos <= 2:
        return pos, 0.15
    if pos <= 9:
        return pos, 0.06
    token = prefix.token_strings[-1]
    if not WORD.fullmatch(token):
        return pos, 0.01
    before = prefix.token_strings[-2]
    if before in AFTER_DETERMINER:
        return pos, 0.06
    if before in AFTER_PREPOSITION:
        return pos, 0.01
    return pos, -0.02

"""Approximate activation of p-82af68dd@100000/layers.15.mlp.down_proj:2409.

What this component is: one rank-one piece of layer 15's MLP down projection. Its input
direction is mostly MLP hidden unit 2409, and it writes that unit's value into the
residual stream. Its activation is typically about 0.06 (std 0.29), and it is set by the
whole residual stream, not by any visible token.

What this program captures, honestly: only a little. Predictions from the visible text
are weak, and this program explains well under 1% of the variance. It uses three facts:
  - position in the document: the first token is near 0, the second is clearly negative
    (about -0.16), and the value rises to about 0.065 after roughly 64 tokens;
  - a newline that ends a sentence lowers it by about 0.10. The sentence end is a
    '.', '?', '!' or ':' at the end of the previous token, or inside the newline token;
  - a token containing a digit raises it by about 0.04.
"""

READS = ()

# mean activation by position in document: first, second, 2-3, 4-15, 16-63, 64 and later
DOC_POSITION_MEAN = (0.0, -0.157, -0.018, 0.025, 0.047, 0.064)
SENTENCE_END = (".", "?", "!", ":")


def step(carry, prefix, upstream):
    label = prefix.document_ids[-1]
    if carry is None or carry[0] != label:
        d = 0  # first token of a new document
    else:
        d = carry[1] + 1
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if d == 0:
        bucket = 0
    elif d == 1:
        bucket = 1
    elif d < 4:
        bucket = 2
    elif d < 16:
        bucket = 3
    elif d < 64:
        bucket = 4
    else:
        bucket = 5
    value = DOC_POSITION_MEAN[bucket]
    ends_sentence = previous.rstrip(" ").endswith(SENTENCE_END) or any(
        c in token for c in SENTENCE_END
    )
    if "\n" in token and ends_sentence:
        value -= 0.10
    if any(c.isdigit() for c in token):
        value += 0.037
    return (label, d), value

"""Exception phrases and "other"-type words (layer 15 MLP down_proj, component 2418).

Mostly this component is small, diffuse noise; its large values are negative and come from
exception phrases. A phrase opens at an exclusion word (besides, except, aside, apart,
addition, 除了, 除去) and closes at its comma or at its closing 外 / 之外 / 以外
("apart from his wife,", "除了产卵之外,"). The closing 外/之外/以外 is strongly negative
when it closes an open phrase; the closing comma is moderately negative. Words that
add or exclude something (other, else, further, additional, ...) are mildly negative.
Negative-polarity words (no, any, never, nothing, anything) are slightly positive.
Everything else is predicted as 0.
"""

READS = ()

# Words that open an exception or addition phrase ("besides", "除了", ...).
CUES = {"besides", "except", "aside", "apart", "excluding", "addition", "除了", "除去", "除卻", "除"}
# Words that close one in Chinese: "除…之外", "除…以外", "…外".
CLOSERS = {"外", "之外", "以外"}
# Commas that end a phrase.
COMMAS = {",", "，", "、"}
# Words meaning "other / additional / else" (on their own, mildly negative).
OTHERS = {"other", "else", "further", "additional", "otherwise", "rest", "remaining", "another", "others", "其他"}
# Weakly negative continuation words.
NEG_WEAK = {"next", "more", "only", "then"}
# Negative-polarity words, slightly positive.
POS = {"no", "any", "never", "none", "nothing", "anything", "neither"}

WINDOW = 14  # an open phrase closes after this many tokens


def step(carry, prefix, upstream):
    """carry = (document id, tokens since the open phrase's cue, or None if no phrase is open)."""
    tok = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    age = carry[1] if carry is not None and carry[0] == doc else None
    if age is not None:
        age = age + 1 if age < WINDOW else None
    value = 0.0
    if tok in CLOSERS:
        value, age = (-18.4, None) if age is not None else (-2.6, None)
    elif tok in COMMAS and age is not None:
        value, age = -3.8, None
    elif tok in OTHERS:
        value = -0.9
    elif tok in NEG_WEAK:
        value = -0.2
    elif tok in POS:
        value = 0.3
    if tok in CUES:
        age = 0
    return (doc, age), value

"""Layer 15 MLP down_proj, component 2425: a weak, mostly negative word-class signal.

What it does: it predicts the component's activation from the word being read, with no
look-ahead. Its activation is near zero on punctuation, digits, spaces and code symbols,
and mildly negative on words. It is most negative on:
  - hyphen-led suffixes such as "-based", "-related", "-specific" (about -0.6),
  - adjectives that open a noun phrase (right after "the/a/of/in/..."), and CJK or kana
    characters, and word-piece continuations (about -0.2),
  - other adjectives and rarer English words (about -0.12).
Common English words are close to zero (about -0.04).

Why these classes: the component's large negative values sit on modifiers that come just
before a head noun, and on word pieces inside a longer word. The sign is not fully
predictable from the word, so this is a class-mean predictor, not a rule that explains
each spike. Its variance explained is small (under 1% on training rows).
"""

import functools
import re

import wordfreq
from wordnet import parts_of_speech

READS = ()

DETERMINERS = {"the", "a", "an", "this", "that", "these", "those", "its", "their", "his", "her", "my", "our", "your"}
PREPOSITIONS = {"of", "in", "on", "for", "with", "to", "from", "by", "at", "as", "into", "about", "between", "among", "under", "over"}
CJK = re.compile(r"[぀-ヿ一-鿿가-힯]")


@functools.lru_cache(maxsize=None)
def is_adjective(word):
    return "adjective" in parts_of_speech(word)


@functools.lru_cache(maxsize=None)
def zipf(word):
    return wordfreq.zipf_frequency(word, "en")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    previous = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()
    if token.startswith("-") and len(token) > 1:
        return carry, -0.58
    if CJK.search(token):
        return carry, -0.21
    if not word.isalpha():
        return carry, 0.0
    if not token.startswith(" "):
        return carry, -0.18  # continuation piece of a longer word
    if is_adjective(word):
        if previous in DETERMINERS or previous in PREPOSITIONS:
            return carry, -0.21
        return carry, -0.12
    if zipf(word) < 5:
        return carry, -0.12
    return carry, -0.04

"""Layer 15 MLP hidden unit 2427 (component down_proj:2427), predicted by word-class rules.

What the component is: one rank-one piece of the MLP down projection. Its activation is almost
exactly the MLP hidden unit 2427 (silu(gate) * up), and it sits near -0.2 most of the time. It
goes strongly negative in a few places:
- just after a figure, table, section or chapter label ("Figure", "Fig", "Table", ...): the
  space, period or number that starts the label's number, e.g. "Figure [ ]4A", "Table [ ]2";
- on the first token after an opening "<think>" tag (strongest) or a closing "</think>" tag;
- on file-path and file-extension tokens ("usr", "cat", "workspace", ".rs", ".ts", "/lib");
- on hesitation words ("Wait", "however") and negation stems ("don", "didn", "isn").
Newlines and plain spaces are a bit negative, and conjunctions ("and", "that", "with") are
slightly above the baseline.

This program predicts the activation from the current token and the one or two tokens before
it, using those word classes and constant values. It is a rough model: on the eval rows it
explains about 1.5% of the variance (r = 0.13). The activation is spread over many tokens with
no shared concept. A per-token lookup table reaches roughly 5% on held-out training rows, so the
rules trade some of that for readability.
"""

READS = ()

LABEL_WORDS = {"Figure", "Fig", "Table", "Section", "Chapter", "Example", "Appendix", "Eq"}
LABEL_NEXT = {" ", "\xa0", ".", "~", " ("}  # what comes between a label word and its number
PATH_WORDS = {"cat", "usr", "tmp", "workspace", "bash", "npm", "/local", "/lib", "/src", "/bin"}
HEDGE_WORDS = {"Wait", "however"}  # self-correction words that start a new thought
FILE_EXTENSIONS = {".ts", ".rs", ".go", ".py", ".js", ".com", ".S"}
NEGATION_STEMS = {"don", "doesn", "didn", "isn", "couldn", "wasn", "won", "aren"}
CONJUNCTIONS = {"and", "that", "with", "or", "but", "which", "how", "where", "when", "than"}
NEWLINES = {"\n", "\n\n", ".\n", ".\n\n"}

BASELINE = -0.2  # the component's typical value


def value_of(token, before, before_before):
    """The predicted activation for `token`, given the tokens just before it."""
    if before == "<think>":
        return -7.0  # the first token of a reasoning block
    if before == "</think>":
        return -3.5  # the first token after a reasoning block closes
    if token in LABEL_NEXT and before.strip() in LABEL_WORDS:
        return -5.0  # just after a figure, table or section label, where its number comes
    if token == " " and before_before.strip() in LABEL_WORDS:
        return -5.0
    if token == " ":
        return -0.5
    if token in NEWLINES:
        return -0.3
    if token.strip() in PATH_WORDS or token in FILE_EXTENSIONS or token.strip() in HEDGE_WORDS:
        return -1.3
    if token.strip() in NEGATION_STEMS:
        return -0.8
    if token.strip() in CONJUNCTIONS:
        return -0.15
    return BASELINE


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    ids = prefix.document_ids
    # A new document starts a fresh context: earlier tokens of other documents do not count.
    start = len(ids) - 1
    while start > 0 and ids[start - 1] == ids[-1]:
        start -= 1
    token = strings[-1]
    before = strings[-2] if len(strings) - 2 >= start else ""
    before_before = strings[-3] if len(strings) - 3 >= start else ""
    return None, float(value_of(token, before, before_before))

"""layers.15.mlp.down_proj:2431, a single MLP unit's write that predicts "heading" contexts.

This component reads (almost only) MLP hidden unit 2431 of layer 15 and writes a fixed
direction that raises the odds of ":" or a line break coming next. Its activation is large
in a few templated places and near zero elsewhere. This program predicts the large cases:

- A chat-template role name right after "<|im_start|>": "assistant" (~7), "user" (~5).
- Wikidata-style relation phrases: "instance of" (~15), "located in", and "of"/"in"/"at"/
  "entity" after a relation noun such as "country", "member", "place", "educated",
  "territorial" (~5).
- "See also" (~30) and "External links" (~15).
- Section-heading words ("References", "Parameters", "Args", "Notes", ...) that open a short,
  capitalised line with no sentence punctuation yet (~8), and other capitalised words opening
  such a line (~0.5). A heading word right after "[" (~6).

Everything else is 0. The rest of the variance is a diffuse, sign-varying background that
no simple rule captures.
"""
READS = ()

# Words that open section headings and labels in documents.
HEADINGS = {
    "references", "external", "see", "notes", "further", "parameters", "returns",
    "args", "career", "history", "changes", "materials", "personal", "features",
    "summary", "details", "related", "links", "description", "command", "current",
}
# Nouns that head Wikidata-style "X of / X in" relation phrases.
RELATION_NOUNS = {" instance", " country", " member", " place", " located", " educated", " territorial"}
# Characters that end a sentence or set off a clause: a title line has none yet.
PUNCT = set(".,:;!?()[]{}\"'")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    # A new document starts a fresh line; the model also resets attention there.
    new_doc = len(prefix.token_ids) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    prev = "" if new_doc else prefix.token_strings[-2]
    # Carry the state of the current line: its token count, whether its first word is
    # capitalised, and whether it has any punctuation yet.
    if carry is None or new_doc:
        carry = {"n": 0, "upper": False, "punct": False}
    word = cur.strip()
    if "\n" in cur:
        carry = {"n": 0, "upper": False, "punct": False}
    else:
        carry = dict(carry, n=carry["n"] + 1)
        if carry["n"] == 1:
            carry["upper"] = word[:1].isupper()
        if any(ch in PUNCT for ch in cur):
            carry["punct"] = True

    if prev == "<|im_start|>":
        return carry, {"assistant": 7.0, "user": 5.0}.get(word, 0.0)
    if prev == " instance" and word == "of":
        return carry, 15.0
    if prev == "See" and word == "also":
        return carry, 30.0
    if prev == "External" and word == "links":
        return carry, 15.0
    if prev in RELATION_NOUNS and word in {"of", "in", "at", "entity"}:
        return carry, 5.0
    if prev == " located" and word == "in":
        return carry, 5.0
    if prev == "[" and word.lower() in HEADINGS:
        return carry, 6.0
    title_line = carry["upper"] and not carry["punct"] and carry["n"] <= 2
    if title_line and word.lower() in HEADINGS:
        return carry, 8.0
    if title_line:
        return carry, 0.5
    return carry, 0.0
